insert into public.freelance_level5_module5_assessment(position,prompt,option_a,option_b,option_c,option_d,correct_option,explanation) values
(1,'¿Qué debe ocurrir antes de abrir una nueva célula comercial?','Tener únicamente más leads','Comprobar readiness de demanda, proceso, liderazgo, economía y riesgos','Contratar primero y medir después','Copiar la estructura de otro equipo','B','EXPANDE exige evidencia multidimensional antes de aumentar estructura.'),
(2,'En EXPANDE, ¿qué significa que el proceso sea repetible?','Que nunca cambie','Que el resultado dependa de una persona clave','Que exista una forma de trabajo documentada y suficientemente estable para reproducirse','Que todas las ventas sean iguales','C','Escalar requiere un proceso transferible, no dependencia de héroes.'),
(3,'Hay demanda alta pero también retrabajo alto y decisiones centralizadas. ¿Qué conviene?','Duplicar inmediatamente el equipo','Estabilizar calidad y autonomía antes de expandir','Ocultar el retrabajo','Prometer más capacidad','B','La expansión amplifica tanto fortalezas como defectos.'),
(4,'¿Para qué sirve un experimento controlado de expansión?','Para garantizar ventas','Para aprender con alcance, inversión e indicadores limitados antes de escalar','Para evitar medir','Para sustituir al supervisor','B','Un piloto reduce exposición y produce evidencia.'),
(5,'En CELULA, ¿qué elemento evita que dos áreas crean ser dueñas del mismo resultado?','Más reuniones','Un dueño explícito con entregable y límites definidos','Un nombre nuevo para el equipo','Un KPI sin responsable','B','La propiedad clara reduce zonas grises.'),
(6,'¿Cómo debe definirse el span of control?','Con un número universal','Solo por antigüedad','Según complejidad, madurez, variabilidad y carga de coordinación','Por tamaño físico de oficina','C','La capacidad de liderazgo depende del contexto.'),
(7,'¿Qué significa preparar a un nuevo supervisor?','Ascenderlo automáticamente','Dar permisos completos desde el primer día','Validar readiness y ampliar autoridad gradualmente dentro del proceso formal','Eliminar checkpoints','C','Preparación y promoción son procesos relacionados pero no equivalentes.'),
(8,'Una matriz de decisiones debe aclarar principalmente:','Quién decide, consulta, informa y escala','Quién vende más','Quién tiene más antigüedad','Quién puede omitir evidencia','A','La matriz hace explícita la distribución de autoridad.'),
(9,'¿Cuál es el error de tratar la gestión del cambio como un anuncio?','Comunicar demasiado','Ignorar conductas, soporte, adopción y aprendizaje necesarios para la transición','Medir indicadores','Hacer un piloto','B','La adopción requiere transición operativa, no solo comunicación.'),
(10,'En CAMBIA, el mínimo cambio viable sirve para:','Cambiar todo al mismo tiempo','Probar la hipótesis con exposición limitada y aprender antes de ampliar','Evitar feedback','Garantizar adopción','B','Reduce riesgo y acelera aprendizaje verificable.'),
(11,'Si un piloto mejora velocidad pero empeora calidad, ¿qué corresponde?','Escalarlo por la mejora de velocidad','Ignorar calidad','Revisar evidencia, ajustar o revertir según criterios definidos','Inventar una meta nueva','C','El gobierno del cambio considera resultados equilibrados y criterios de reversa.'),
(12,'¿Qué NO debe producir automáticamente una expansión organizacional?','Nuevos handoffs documentados','Revisión de capacidad','Ascensos o permisos fuera del proceso formal','Nuevos checkpoints','C','Los cambios de estructura no sustituyen las reglas formales de carrera y autorización.')
