-- Compás Academy · Nivel 5 · Módulo 5 · Evaluación formativa
-- 12 reactivos. Aprobación: 80% (mínimo 10/12).
create table if not exists public.freelance_level5_module5_assessment (
 id bigint generated by default as identity primary key, position integer not null unique, prompt text not null,
 option_a text not null, option_b text not null, option_c text not null, option_d text not null,
 correct_option char(1) not null check(correct_option in('A','B','C','D')), explanation text not null, created_at timestamptz not null default now());
alter table public.freelance_level5_module5_assessment enable row level security;
revoke all on public.freelance_level5_module5_assessment from public,anon,authenticated;
grant all on public.freelance_level5_module5_assessment to service_role;
on conflict(position) do update set prompt=excluded.prompt,option_a=excluded.option_a,option_b=excluded.option_b,option_c=excluded.option_c,option_d=excluded.option_d,correct_option=excluded.correct_option,explanation=excluded.explanation;